module min_rounding_error ( input clk, input rst_n, input start, input [2:0] n, input [31:0] numbers [7:0], output reg [31:0] result, output reg done ); reg [1:0] state; reg [31:0] fractional_count, fractional_sum; reg [3:0] i, total_nums; reg [31:0] result; reg done; always @(posedge clk) begin if (!rst_n) begin state <= 2'b00; fractional_count <= 32'b0; fractional_sum <= 32'b0; i <= 4'd0; total_nums <= 4'd0; result <= 32'b0; done <= 1'b0; end else begin if (state == 2'b00) begin // IDLE if (start) begin total_nums <= 2 * n; i <= 4'd0; fractional_count <= 32'b0; fractional_sum <= 32'b0; state <= 2'b01; // COLLECT end end else if (state == 2'b01) begin // COLLECT if (i < total_nums) begin [31:0] num; num = numbers[i]; [15:0] frac = num[15:0]; if (frac != 16'd0) begin fractional_count <= fractional_count + 1; fractional_sum <= fractional_sum + frac; end i <= i + 1; end else begin state <= 2'b10; // CALCULATE end end else if (state == 2'b10) begin // CALCULATE integer fractional_c = fractional_count; integer n_val = n; integer integer_count = total_nums - fractional_c; integer min_up = fractional_c - n_val; if (min_up < 0) min_up = 0; integer max_up = n_val; if (max_up > fractional_c) max_up = fractional_c; integer k_opt = (fractional_sum + 32'h00008000) >> 1; if (k_opt < min_up) k_opt = min_up; else if (k_opt > max_up) k_opt = max_up; integer target = k_opt * 32'h00008000; integer error = fractional_sum - target; integer abs_error; if (error < 0) abs_error = -error; else abs_error = error; result <= abs_error; done <= 1'b1; state <= 2'b11; // DONE end else begin // DONE end end end end module